#include <cctype>
#include <string>

std::string apiMacroFor(bool buildingTheDll)
{
    return buildingTheDll ? "__declspec(dllexport)" : "__declspec(dllimport)";
}

std::string exportsSymbol(const std::string& projectName)
{
    std::string out;
    for (char c : projectName)
    {
        const unsigned char u{ static_cast<unsigned char>(c) };
        out += std::isalnum(u) ? static_cast<char>(std::toupper(u)) : '_';
    }
    return out + "_EXPORTS";
}

unitTests:
TEST("building the DLL") { CHECK_EQ(apiMacroFor(true), std::string("__declspec(dllexport)")); }
TEST("using the DLL") { CHECK_EQ(apiMacroFor(false), std::string("__declspec(dllimport)")); }
TEST("the lesson's project") { CHECK_EQ(exportsSymbol("StoneMath"), std::string("STONEMATH_EXPORTS")); }
TEST("other characters") { CHECK_EQ(exportsSymbol("my-lib 2"), std::string("MY_LIB_2_EXPORTS")); }
TEST("already upper case") { CHECK_EQ(exportsSymbol("AUDIO"), std::string("AUDIO_EXPORTS")); }

